import json
import urllib.request
import urllib.error
import urllib.parse

API_KEY = "09NOtKbQBE2goFtwD9NwpSBHkBzVmZ4K"
BASE_URL = "http://127.0.0.1:8108"

def request(path, method="GET", data=None, params=None):
    if params:
        query_string = urllib.parse.urlencode(params)
        url = f"{BASE_URL}{path}?{query_string}"
    else:
        url = f"{BASE_URL}{path}"

    req = urllib.request.Request(url, method=method)
    req.add_header("X-TYPESENSE-API-KEY", API_KEY)
    if data is not None:
        req.add_header("Content-Type", "application/json")
        body = json.dumps(data).encode("utf-8")
    else:
        body = None

    try:
        with urllib.request.urlopen(req, data=body) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        print(f"HTTP Error {e.code}: {e.read().decode('utf-8')}")
        raise e

# 1. Delete collection if exists
try:
    print("Deleting existing collection...")
    request("/collections/knowledge_base", method="DELETE")
except Exception:
    print("Collection did not exist or could not be deleted.")

# 2. Create collection
schema = {
    "name": "knowledge_base",
    "fields": [
        {"name": "id", "type": "string"},
        {"name": "title", "type": "string"},
        {"name": "body", "type": "string"},
        {"name": "embedding", "type": "float[]", "num_dim": 8}
    ]
}
print("Creating collection...")
create_res = request("/collections", method="POST", data=schema)

# 3. Load and index documents
with open("/home/user/kbsearch/data/documents.json") as f:
    documents = json.load(f)

for doc in documents:
    request("/collections/knowledge_base/documents", method="POST", data=doc)

# 4. Try a keyword search
print("\n--- Testing Keyword Search ---")
kw_res = request("/collections/knowledge_base/documents/search", params={
    "q": "speed up slow website",
    "query_by": "title,body"
})
for hit in kw_res.get("hits", []):
    print(f"ID: {hit['document']['id']}, Hit keys: {list(hit.keys())}")
    print(f"Full hit: {hit}")

# 5. Try semantic search
print("\n--- Testing Semantic Search ---")
with open("/home/user/kbsearch/data/query_vectors.json") as f:
    query_vectors = json.load(f)
q_vec = query_vectors["speed up slow website"]
q_vec_str = ",".join(map(str, q_vec))

sem_res = request("/collections/knowledge_base/documents/search", params={
    "q": "*",
    "vector_query": f"embedding:([{q_vec_str}],k:10)"
})
for hit in sem_res.get("hits", []):
    print(f"ID: {hit['document']['id']}, Hit keys: {list(hit.keys())}")
    print(f"Full hit: {hit}")

# 6. Try hybrid search
print("\n--- Testing Hybrid Search ---")
hybrid_res = request("/collections/knowledge_base/documents/search", params={
    "q": "speed up slow website",
    "query_by": "title,body",
    "vector_query": f"embedding:([{q_vec_str}],k:10,alpha:0.5)"
})
for hit in hybrid_res.get("hits", []):
    print(f"ID: {hit['document']['id']}, Hit keys: {list(hit.keys())}")
    print(f"Full hit: {hit}")

